  id?: string;
  className?: string;
  background?: string;
  particleSize?: number;
  minSize?: number;
  maxSize?: number;
  speed?: number;
  particleColor?: string;
  particleDensity?: number;
};
// @tsparticles/react v4 replaced initParticlesEngine with a provider.
export const SparklesCore = (props: ParticlesProps) => (
  <ParticlesProvider init={loadSlim}>
    <SparklesInner {...props} />
  </ParticlesProvider>
);

